// Scroll follows the browser's native scrolling and never captures wheel/touch input.
export function initCaseMotion({getMotion,react}) {
  const sections=[...document.querySelectorAll('main>section')];
  const chapters=[['Welcome','happy','Welcome! Scroll to explore the story. Tap me for a little hello.'],['The idea','thinking','Familiar actions first. The blockchain details can come second.'],['Try it','coding','Choose an asset and try a sample trade. I’m here to help.'],['The design','happy','Purple belongs to N.E.D. Hover or focus a screen to look closer.'],['Current status','thinking','Built, simulated, or planned? These cards tell you which is which.'],['Under the hood','coding','Follow the layers: interface, identity, then network.'],['What’s next','happy','You made it! Try the demo, or head back to meet Teichi.']];
  const rail=document.createElement('nav');rail.className='story-rail';rail.setAttribute('aria-label','Case study chapters');
  sections.forEach((section,i)=>{section.id ||= `ned-chapter-${i}`;const a=document.createElement('a');a.href=`#${section.id}`;a.innerHTML=`<span>${String(i+1).padStart(2,'0')}</span><b>${chapters[i][0]}</b>`;a.setAttribute('aria-label',chapters[i][0]);rail.append(a);});document.body.append(rail);
  const progress=document.createElement('div');progress.className='reading-progress';progress.setAttribute('aria-hidden','true');document.body.append(progress);
  const guide=document.querySelector('.may-guide'),slot=document.createElement('div');slot.className='may-guide-slot';guide.before(slot);slot.append(guide);
  const tools=document.createElement('div');tools.className='may-actions';tools.innerHTML='<button type="button" data-may-action="hello">Say hello ♡</button><button type="button" data-may-action="hint">Mây’s note</button><button type="button" data-may-action="next">Next chapter ↓</button>';
  guide.append(tools);const collapse=document.createElement('button');collapse.className='may-collapse';collapse.type='button';collapse.textContent='−';collapse.setAttribute('aria-label','Minimize Mây guide');collapse.setAttribute('aria-expanded','true');guide.append(collapse);
  let minimized=false,chapter=-1,pending=false,lastY=scrollY,scrollTimer,hoverTimer,lastHint=0;
  collapse.onclick=()=>{minimized=!minimized;guide.classList.toggle('is-minimized',minimized);collapse.textContent=minimized?'+':'−';collapse.setAttribute('aria-expanded',String(!minimized));collapse.setAttribute('aria-label',minimized?'Expand Mây guide':'Minimize Mây guide');};
  const smallScreen=matchMedia('(max-width:600px)');
  if(smallScreen.matches)collapse.click();
  smallScreen.addEventListener('change',e=>{if(e.matches!==minimized)collapse.click();});
  tools.addEventListener('click',e=>{const action=e.target.closest('button')?.dataset.mayAction;if(action==='hello'){react('happy','Xin chào! A little wave from your cloud companion.');guide.classList.remove('may-wave');void guide.offsetWidth;guide.classList.add('may-wave');}if(action==='hint')react(chapters[chapter][1],chapters[chapter][2]);if(action==='next'){const next=sections[(chapter+1)%sections.length];next.scrollIntoView({behavior:getMotion()?'smooth':'instant',block:'start'});next.setAttribute('tabindex','-1');next.focus({preventScroll:true});}});
  const revealTargets=[...document.querySelectorAll('.section-top,.story-grid>*,.principles article,.demo-intro>h2,.demo-device,.design-strip,.gallery figure,.status-grid article,.reality-note,.architecture>div,.closing>*,.source-links')];
  const observer=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('is-revealed');observer.unobserve(e.target);}}),{threshold:.1});
  revealTargets.forEach((el,i)=>{el.classList.add('scroll-reveal');el.style.setProperty('--reveal-delay',`${i%3*65}ms`);observer.observe(el);});
  // Hover and keyboard focus share the same character response.
  const contexts=[['.principles article','thinking','Less jargon, more clarity. That’s the idea.'],['.gallery figure','happy','A closer look at the original product design. These figures are samples.'],['.status-grid article','thinking','The label matters: implementation, demo, and roadmap are different.'],['.architecture>div','coding','One layer at a time. This is how the app fits together.']];
  for(const [selector,mood,message] of contexts)document.querySelectorAll(selector).forEach(el=>{el.tabIndex=0;const show=()=>{clearTimeout(hoverTimer);hoverTimer=setTimeout(()=>{if(performance.now()-lastHint>1800){react(mood,message);lastHint=performance.now();}},180);};el.addEventListener('pointerenter',show);el.addEventListener('focus',show);el.addEventListener('pointerleave',()=>clearTimeout(hoverTimer));el.addEventListener('blur',()=>clearTimeout(hoverTimer));});
  const hero=document.querySelector('.hero-art'),front=hero.querySelector('.front-screen'),back=hero.querySelector('.back-screen');
  let px=0,py=0;hero.addEventListener('pointermove',e=>{if(e.pointerType==='touch')return;const r=hero.getBoundingClientRect();px=(e.clientX-r.left)/r.width-.5;py=(e.clientY-r.top)/r.height-.5;schedule();});hero.addEventListener('pointerleave',()=>{px=py=0;schedule();});
  function update(){pending=false;const height=innerHeight,top=scrollY,total=document.documentElement.scrollHeight-height;progress.style.transform=`scaleX(${total>0?top/total:0})`;let next=0;sections.forEach((s,i)=>{if(s.getBoundingClientRect().top<height*.48)next=i;});
    if(next!==chapter){chapter=next;[...rail.children].forEach((a,i)=>{if(i===chapter)a.setAttribute('aria-current','location');else a.removeAttribute('aria-current');});react(chapters[chapter][1],chapters[chapter][2]);}
    const box=slot.getBoundingClientRect(),inPlace=box.top>80&&box.bottom<height-35;guide.classList.toggle('is-docked',!inPlace);guide.dataset.chapter=String(chapter+1);
    const enabled=getMotion();document.body.classList.toggle('case-motion-enabled',enabled);const travel=Math.max(0,Math.min(1,top/(height*.9)));hero.style.setProperty('--scroll-shift',`${enabled?travel*60:0}px`);front.style.translate=enabled?`${px*20}px ${py*12-travel*28}px`:'none';back.style.translate=enabled?`${-px*16}px ${-py*10+travel*24}px`:'none';
    sections.forEach(s=>{const r=s.getBoundingClientRect();if(r.bottom>0&&r.top<height)s.style.setProperty('--section-progress',String(enabled?Math.max(0,Math.min(1,(height-r.top)/(height+r.height))):.5));});lastY=top;
  }
  function schedule(){if(!pending){pending=true;requestAnimationFrame(update);}}
  window.addEventListener('scroll',()=>{if(getMotion()&&Math.abs(scrollY-lastY)>3){guide.classList.add('is-travelling');guide.style.setProperty('--travel-lean',scrollY>lastY?'3deg':'-3deg');clearTimeout(scrollTimer);scrollTimer=setTimeout(()=>guide.classList.remove('is-travelling'),180);}schedule();},{passive:true});window.addEventListener('resize',schedule);window.addEventListener('ned-motion-change',schedule);document.fonts.ready.then(schedule);update();
}
